148	  }
149	
150	  // Check if it's the last line
151	  if (invoice.lines.length === 1) {
152	    return fail('NO_LINES');
153	  }
154	
155	  // Copy lines array without the line at lineIndex
156	  const newLines = invoice.lines.filter((_, index) => index !== lineIndex);
157	
158	  return ok({
