169	 */
170	export function issueInvoice(invoice, existingNumbers) {
171	  // Check invoice is draft
172	  if (invoice.status !== 'draft') {
173	    return fail('NOT_DRAFT');
174	  }
175	
176	  // Generate next invoice number
