/**
 * Render an invoice as plain text.
 * @param {{ number?: string, customerId: string, lines: Array<{ qty: number, name: string, unitPrice: number, discountPercent?: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  // First line: invoice number or DRAFT
  const numberLine = invoice.number ?? 'DRAFT';

  // Get customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';

  // Build line items
  const lineItems = invoice.lines
    .map((line) => {
      const total = lineTotal(line);
      const unitPriceFormatted = formatEuros(line.unitPrice);
      const totalFormatted = formatEuros(total);
      let lineStr = `${line.qty} × ${line.name} @ ${unitPriceFormatted} = ${totalFormatted}`;
      if (line.discountPercent !== undefined && line.discountPercent > 0) {
        const discount = Math.round(total * line.discountPercent / 100);
        const discountFormatted = formatEuros(discount);
        lineStr += ` (${line.discountPercent}% off: -${discountFormatted})`;
      }
      return lineStr;
    });

  // Calculate and format totals
  const totals = invoiceTotals(invoice);
  const output = [numberLine, customerName, ...lineItems];

  // Add subtotal and discount if discount exists
  if (totals.discount > 0) {
    output.push(`Subtotal: ${formatEuros(totals.subtotal)}`);
    output.push(`Discount: -${formatEuros(totals.discount)}`);
  }

  output.push(`Total: ${formatEuros(totals.total)}`);

  return output.join('\n');
}

