test('invoiceTotals: without discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8 }],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  assert.equal(totals.subtotal, 76000);
  assert.equal(totals.discount, 0);
  assert.equal(totals.total, 76000);
});

test('invoiceTotals: with single line discount', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DEV-HOUR', qty: 8, discountPercent: 10 }],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // 8 * 9500 = 76000, 10% = 7600
  assert.equal(totals.subtotal, 76000);
  assert.equal(totals.discount, 7600);
  assert.equal(totals.total, 68400);
});

test('invoiceTotals: with multiple line discounts', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 10 },
      { sku: 'DES-HOUR', qty: 5, discountPercent: 20 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Dev: 8 * 9500 = 76000, 10% = 7600
  // Des: 5 * 8500 = 42500, 20% = 8500
  // Subtotal: 118500, Discount: 16100, Total: 102400
  assert.equal(totals.subtotal, 118500);
  assert.equal(totals.discount, 16100);
  assert.equal(totals.total, 102400);
});

test('invoiceTotals: with 100% discount on one line', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [
      { sku: 'DEV-HOUR', qty: 8, discountPercent: 100 },
      { sku: 'DES-HOUR', qty: 5 },
    ],
  });

  assert.ok(result.ok);
  const totals = invoiceTotals(result.value);
  // Dev: 8 * 9500 = 76000, 100% = 76000
  // Des: 5 * 8500 = 42500, 0% = 0
  // Subtotal: 118500, Discount: 76000, Total: 42500
  assert.equal(totals.subtotal, 118500);
  assert.equal(totals.discount, 76000);
  assert.equal(totals.total, 42500);
});

test('invoiceTotals: clamps negative total to 0', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', qty: 1, name: 'Development (hour)', unitPrice: 9500, vatRate: 21, discountPercent: 110 },
    ],
  };

