  assert.ok(text.includes('12.5% off'));
  // 8 * 9500 = 76000, 12.5% = 9500
  assert.ok(text.includes('-€95.00'));
  // 76000 - 9500 = 66500
  assert.ok(text.includes('€665.00'));
});

